import{_ as a}from"./chunks/channels-list.Cv5XW_0Z.js";import{_ as n,o as t,c as o,a2 as s}from"./chunks/framework.CPHNBVkq.js";const m=JSON.parse('{"title":"Managing Channels","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels-manage.md","filePath":"guide/channels-manage.md"}'),r={name:"guide/channels-manage.md"};function l(i,e,h,c,g,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="managing-channels" tabindex="-1">Managing Channels <a class="header-anchor" href="#managing-channels" aria-label="Permalink to &quot;Managing Channels&quot;">​</a></h1><p>Once you&#39;ve created channels, you can review, edit, and remove them from one place.</p><h2 id="open-your-channels" tabindex="-1">Open your channels <a class="header-anchor" href="#open-your-channels" aria-label="Permalink to &quot;Open your channels&quot;">​</a></h2><p>Go to <strong>Settings → Manage Channels</strong>. You&#39;ll see a list of every channel you&#39;ve set up.</p><p><img src="'+a+'" alt="Managing your channels"></p><h2 id="edit-a-channel" tabindex="-1">Edit a channel <a class="header-anchor" href="#edit-a-channel" aria-label="Permalink to &quot;Edit a channel&quot;">​</a></h2><p>Select a channel to open it for editing. You can change any of its settings:</p><ul><li><strong>Channel Name</strong></li><li><strong>Channel Scope</strong> (Broad or Narrow)</li><li><strong>Category</strong></li><li><strong>Channel Tags</strong></li></ul><p>These are the same fields you set when creating a channel — see <a href="./channels.html">About Channels</a> for what each one does. Make your changes and select <strong>Save</strong>, or <strong>Cancel</strong> to discard them.</p><div class="warning custom-block"><p class="custom-block-title">Changing the category resets your tags</p><p>Tags belong to a category. If you switch a channel to a different category, the tags from the old category no longer apply — review and re-pick your tags after changing it.</p></div><h2 id="tune-a-noisy-or-quiet-channel" tabindex="-1">Tune a noisy or quiet channel <a class="header-anchor" href="#tune-a-noisy-or-quiet-channel" aria-label="Permalink to &quot;Tune a noisy or quiet channel&quot;">​</a></h2><p>If a channel is showing too much or too little, edit it rather than deleting it. Remember that <strong>tags</strong> pick out specific things in the category and <strong>scope</strong> decides how those tags combine — see <a href="./channels.html#how-scope-and-tags-work-together">How scope and tags work together</a>.</p><ul><li><strong>Too much?</strong> Add <strong>tags</strong> so the channel only includes updates about specific things, instead of the whole category. If it already has several tags, switch the scope to <strong>Narrow</strong> so updates must match <em>all</em> of them.</li><li><strong>Too little?</strong> Remove some tags so the channel follows more of its category. If it has several tags, switch the scope to <strong>Broad</strong> so matching <em>any one</em> of them is enough.</li></ul><h2 id="remove-a-channel" tabindex="-1">Remove a channel <a class="header-anchor" href="#remove-a-channel" aria-label="Permalink to &quot;Remove a channel&quot;">​</a></h2><p>Removing a channel stops its updates from appearing in your Pulse feed. Open the channel and choose to delete it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Deleting a channel only affects your feed — it doesn&#39;t change anything for anyone else, and it doesn&#39;t delete the underlying business data. You can always create the channel again later.</p></div>',16)])])}const f=n(r,[["render",l]]);export{m as __pageData,f as default};
